(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.15)*8+Math.cos((x-y)*0.012-t*0.18)*6;
  wy += Math.cos((x-y)*0.011+t*0.17)*7+Math.sin((x+y)*0.013-t*0.22)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*40, 0.13, 1.8, 0.85],
    [200+Math.sin(t*0.38+6)*110, 200+Math.cos(t*0.48+3)*70, 0.075, 2.4, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const n=9, act=aS/n, inh=iS/n, cor=cS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03+ang*6-t*0.8)*0.2;
  const cx2=180+Math.sin(t*0.2)*60, cy2=100+Math.cos(t*0.25)*40;
  const dist2=Math.sqrt((sx-cx2)**2+(sy-cy2)**2), ang2=Math.atan2(sy-cy2,sx-cx2);
  const spiral2 = (Math.sin(dist2*0.06+ang2*5-t*1.8)+Math.sin(dist2*0.045-ang2*3-t*1.0))*0.25;
  const voro = (() => {
    let md = 1e9, md2 = 1e9;
    for (let i = 0; i < 7; i++) {
      const vx = 80+i*60+Math.sin(t*0.3+i*1.7)*25;
      const vy = 40+((i*37)%5)*40+Math.cos(t*0.25+i*2.1)*20;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.4-t*1.5)*0.3;
  })();
  const cross = Math.sin(act*Math.PI*0.5)*Math.sin(inh*Math.PI*0.5)*0.4;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2*0.5+cor*0.3+voro)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.6+cell*0.2+cross*0.1+micro;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.1)*0.15;
  const pal = [
    [5,12,55],[12,45,95],[18,95,125],[25,155,140],[60,185,120],
    [170,195,70],[210,175,55],[215,130,65],[195,85,75],[155,50,85],
    [100,30,75],[50,18,60],[5,12,55]
  ];
  let idx = (v+hueShift)*(pal.length-1);
  idx = ((idx%1)+1)%1*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0, 1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60))|0
  ];
}
